// === Tab: mySketch ===
let particles = [];
let flowField;
let colorScheme;

function setup() {
  createCanvas(windowWidth, windowHeight);
  pixelDensity(1);
  colorMode(HSB, 360, 100, 100, 1);

  flowField = new FlowField();
  colorScheme = new ColorScheme();

  background(0);
}

function draw() {
  fill(0, 0, 0, 0.05);
  rect(0, 0, width, height);

  flowField.update();

  if (((window.isBeat || false) || (typeof window.is_silent !== 'undefined' ? !window.is_silent : mouseIsPressed))) {
    for (let i = 0; i < 5; i++) {
      particles.push(new Particle((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))));
    }
  }

  for (let i = particles.length - 1; i >= 0; i--) {
    let p = particles[i];
    p.follow(flowField);
    p.update();
    p.display();

    if (p.isDead()) {
      particles.splice(i, 1);
    }
  }
}

class FlowField {
  constructor() {
    this.resolution = 10;
    this.cols = ceil(width / this.resolution);
    this.rows = ceil(height / this.resolution);
    this.field = new Array(this.cols * this.rows);
    this.zoff = 0;
  }

  update() {
    let xoff = 0;
    for (let x = 0; x < this.cols; x++) {
      let yoff = 0;
      for (let y = 0; y < this.rows; y++) {
        let index = x + y * this.cols;
        let angle = noise(xoff, yoff, this.zoff) * TWO_PI * 4;
        let v = p5.Vector.fromAngle(angle);
        v.setMag(1);
        this.field[index] = v;
        yoff += 0.1;
      }
      xoff += 0.1;
    }
    this.zoff += 0.01;
  }
}

class Particle {
  constructor(x, y) {
    this.pos = createVector(x, y);
    this.vel = createVector(0, 0);
    this.acc = createVector(0, 0);
    this.maxSpeed = 4;
    this.lifespan = 255;
    this.color = colorScheme.getColor(x / width, y / height);
  }

  follow(flowfield) {
    let x = floor(this.pos.x / flowfield.resolution);
    let y = floor(this.pos.y / flowfield.resolution);
    var index = x + y * flowfield.cols;
    let force = flowfield.field[index];
    this.applyForce(force);
  }

  applyForce(force) {
    this.acc.add(force);
  }

  update() {
    this.vel.add(this.acc);
    this.vel.limit(this.maxSpeed);
    this.pos.add(this.vel);
    this.acc.mult(0);
    this.lifespan -= 2;
  }

  display() {
    stroke(this.color, this.lifespan);
    strokeWeight(2);
    point(this.pos.x, this.pos.y);
  }

  isDead() {
    return this.lifespan < 0 || this.pos.x < 0 || this.pos.x > width || this.pos.y < 0 || this.pos.y > height;
  }
}

class ColorScheme {
  constructor() {
    this.baseHue = random(360);
    this.hueRange = 60;
  }

  getColor(x, y) {
    let hue = (this.baseHue + this.hueRange * sin(x * PI) * cos(y * PI)) % 360;
    return color(hue, 80, 100);
  }
}

function windowResized() {
  resizeCanvas(windowWidth, windowHeight);
  background(0);
  flowField = new FlowField();
}

